CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', account_type text NOT NULL DEFAULT 'adult_student' CHECK (account_type IN ('family','adult_student','teacher')), active_learner_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY edit_profile ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name,account_type) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name',''),CASE WHEN NEW.raw_user_meta_data->>'account_type' IN ('family','adult_student','teacher') THEN NEW.raw_user_meta_data->>'account_type' ELSE 'adult_student' END); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user'); RETURN NEW; END $$;
CREATE TRIGGER create_peluqo_account AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();
CREATE TABLE public.learners (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 60), education_level text NOT NULL DEFAULT 'Primaria', grade_level text NOT NULL DEFAULT '', age_band text NOT NULL DEFAULT '9–12', avatar_config jsonb NOT NULL DEFAULT '{"color":"sunburst"}', preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.learners TO authenticated; GRANT ALL ON public.learners TO service_role;
ALTER TABLE public.learners ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_learners ON public.learners FOR ALL TO authenticated USING(owner_user_id=auth.uid()) WITH CHECK(owner_user_id=auth.uid());
CREATE INDEX learners_owner ON public.learners(owner_user_id);
CREATE FUNCTION public.validate_active_learner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.active_learner_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.learners WHERE id=NEW.active_learner_id AND owner_user_id=NEW.id) THEN RAISE EXCEPTION 'Perfil no autorizado'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_active_profile BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_active_learner();
CREATE TABLE public.subjects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text UNIQUE NOT NULL,description text NOT NULL DEFAULT '',color text NOT NULL DEFAULT 'sunburst',display_order integer NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.subjects TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.subjects TO authenticated; GRANT ALL ON public.subjects TO service_role;
ALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_subjects ON public.subjects FOR SELECT TO anon,authenticated USING(is_active);
CREATE POLICY admin_subjects ON public.subjects FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.topics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_id uuid NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,title text NOT NULL,slug text NOT NULL,description text NOT NULL DEFAULT '',display_order integer NOT NULL DEFAULT 0,UNIQUE(subject_id,slug));
GRANT SELECT ON public.topics TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.topics TO authenticated; GRANT ALL ON public.topics TO service_role;
ALTER TABLE public.topics ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_topics ON public.topics FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.subjects s WHERE s.id=subject_id AND s.is_active));
CREATE POLICY admin_topics ON public.topics FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.lessons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic_id uuid NOT NULL REFERENCES public.topics(id),title text NOT NULL,slug text UNIQUE NOT NULL,description text NOT NULL DEFAULT '',education_level text NOT NULL DEFAULT 'Primaria',estimated_minutes integer NOT NULL DEFAULT 10,cover_image text,content jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.lessons TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.lessons TO authenticated; GRANT ALL ON public.lessons TO service_role;
ALTER TABLE public.lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_lessons ON public.lessons FOR SELECT TO anon,authenticated USING(status='published');
CREATE POLICY admin_lessons ON public.lessons FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lesson_id uuid NOT NULL REFERENCES public.lessons(id) ON DELETE CASCADE,title text NOT NULL,activity_type text NOT NULL,instructions text NOT NULL DEFAULT '',public_config jsonb NOT NULL DEFAULT '{}',points integer NOT NULL DEFAULT 10 CHECK(points BETWEEN 0 AND 100),display_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.activities TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.activities TO authenticated; GRANT ALL ON public.activities TO service_role;
ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_activities ON public.activities FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.lessons l WHERE l.id=lesson_id AND l.status='published'));
CREATE POLICY admin_activities ON public.activities FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.activity_solutions(activity_id uuid PRIMARY KEY REFERENCES public.activities(id) ON DELETE CASCADE,answer_config jsonb NOT NULL,explanation text NOT NULL);
GRANT ALL ON public.activity_solutions TO service_role;
ALTER TABLE public.activity_solutions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.activity_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),learner_id uuid NOT NULL REFERENCES public.learners(id) ON DELETE CASCADE,activity_id uuid NOT NULL REFERENCES public.activities(id) ON DELETE CASCADE,submitted_answer jsonb NOT NULL,score integer NOT NULL,is_correct boolean NOT NULL,feedback jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_attempts TO authenticated; GRANT ALL ON public.activity_attempts TO service_role;
ALTER TABLE public.activity_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_attempts ON public.activity_attempts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.learners l WHERE l.id=learner_id AND l.owner_user_id=auth.uid()));
CREATE INDEX attempts_learner ON public.activity_attempts(learner_id,activity_id);
CREATE TABLE public.lesson_progress(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),learner_id uuid NOT NULL REFERENCES public.learners(id) ON DELETE CASCADE,lesson_id uuid NOT NULL REFERENCES public.lessons(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'started',completion_percentage integer NOT NULL DEFAULT 0,best_score integer NOT NULL DEFAULT 0,completed_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(learner_id,lesson_id));
GRANT SELECT ON public.lesson_progress TO authenticated; GRANT ALL ON public.lesson_progress TO service_role;
ALTER TABLE public.lesson_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_progress ON public.lesson_progress FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.learners l WHERE l.id=learner_id AND l.owner_user_id=auth.uid()));
CREATE TABLE public.achievements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,description text NOT NULL DEFAULT '',lesson_id uuid UNIQUE REFERENCES public.lessons(id) ON DELETE CASCADE,icon text NOT NULL DEFAULT 'star');
GRANT SELECT ON public.achievements TO anon,authenticated; GRANT ALL ON public.achievements TO service_role;
ALTER TABLE public.achievements ENABLE ROW LEVEL SECURITY;
CREATE POLICY visible_achievements ON public.achievements FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.learner_achievements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),learner_id uuid NOT NULL REFERENCES public.learners(id) ON DELETE CASCADE,achievement_id uuid NOT NULL REFERENCES public.achievements(id) ON DELETE CASCADE,earned_at timestamptz NOT NULL DEFAULT now(),UNIQUE(learner_id,achievement_id));
GRANT SELECT ON public.learner_achievements TO authenticated; GRANT ALL ON public.learner_achievements TO service_role;
ALTER TABLE public.learner_achievements ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_achievements ON public.learner_achievements FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.learners l WHERE l.id=learner_id AND l.owner_user_id=auth.uid()));
CREATE FUNCTION public.evaluate_activity(p_learner uuid,p_activity uuid,p_answer jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.activities; sol public.activity_solutions; correct boolean; awarded integer; total integer; done_count integer; earned integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF; PERFORM 1 FROM public.learners WHERE id=p_learner AND owner_user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Perfil no autorizado'; END IF; SELECT ac.* INTO a FROM public.activities ac JOIN public.lessons l ON l.id=ac.lesson_id WHERE ac.id=p_activity AND l.status='published'; IF NOT FOUND THEN RAISE EXCEPTION 'Actividad no disponible'; END IF; SELECT * INTO sol FROM public.activity_solutions WHERE activity_id=p_activity; IF NOT FOUND THEN RAISE EXCEPTION 'Actividad sin evaluación'; END IF; correct=(p_answer=sol.answer_config); awarded=CASE WHEN correct AND NOT EXISTS(SELECT 1 FROM public.activity_attempts WHERE learner_id=p_learner AND activity_id=p_activity AND is_correct) THEN a.points ELSE 0 END; INSERT INTO public.activity_attempts(learner_id,activity_id,submitted_answer,score,is_correct,feedback) VALUES(p_learner,p_activity,p_answer,awarded,correct,jsonb_build_object('explanation',CASE WHEN correct THEN sol.explanation ELSE 'Todavía no. Revisa la explicación y vuelve a intentarlo.' END)); SELECT count(*) INTO total FROM public.activities WHERE lesson_id=a.lesson_id; SELECT count(DISTINCT at.activity_id) INTO done_count FROM public.activity_attempts at JOIN public.activities ac ON ac.id=at.activity_id WHERE at.learner_id=p_learner AND at.is_correct AND ac.lesson_id=a.lesson_id; SELECT coalesce(sum(at.score),0) INTO earned FROM public.activity_attempts at JOIN public.activities ac ON ac.id=at.activity_id WHERE at.learner_id=p_learner AND ac.lesson_id=a.lesson_id; INSERT INTO public.lesson_progress(learner_id,lesson_id,status,completion_percentage,best_score,completed_at) VALUES(p_learner,a.lesson_id,CASE WHEN done_count=total THEN 'completed' ELSE 'started' END,done_count*100/greatest(total,1),earned,CASE WHEN done_count=total THEN now() ELSE NULL END) ON CONFLICT(learner_id,lesson_id) DO UPDATE SET status=excluded.status,completion_percentage=excluded.completion_percentage,best_score=excluded.best_score,completed_at=coalesce(public.lesson_progress.completed_at,excluded.completed_at),updated_at=now(); IF done_count=total THEN INSERT INTO public.learner_achievements(learner_id,achievement_id) SELECT p_learner,id FROM public.achievements WHERE lesson_id=a.lesson_id ON CONFLICT DO NOTHING; END IF; RETURN jsonb_build_object('correct',correct,'points',awarded,'progress',done_count*100/greatest(total,1),'explanation',CASE WHEN correct THEN sol.explanation ELSE 'Todavía no. Revisa la explicación y vuelve a intentarlo.' END); END $$;
REVOKE ALL ON FUNCTION public.evaluate_activity(uuid,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.evaluate_activity(uuid,uuid,jsonb) TO authenticated;
CREATE POLICY own_document_files ON storage.objects FOR ALL TO authenticated USING(bucket_id='learner-documents' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='learner-documents' AND (storage.foldername(name))[1]=auth.uid()::text);